/**
 * Handler for ContactTrigger.
 *
 * Original per-record behaviour preserved:
 *   BEFORE: if Contact.AccountId exists,
 *             - populate MailingCountry from Account.BillingCountry when blank
 *             - on INSERT, populate LeadSource from Account.AccountSource when blank
 *   AFTER INSERT: for each contact (in trigger order) that has AccountId and a non-blank
 *                 Phone, if the Account's Phone is blank set it to that contact's Phone.
 *                 When several contacts of the same Account qualify, only the FIRST one
 *                 (in trigger order) wins, because once the Account's phone is set the
 *                 blank check fails for the subsequent ones.
 *
 * Budget for up to 200 contacts:
 *   - 1 SOQL in before  (accounts for BillingCountry / AccountSource)
 *   - 1 SOQL in after   (accounts for Phone)
 *   - 1 DML in after    (single update of accounts needing a phone)
 */
public with sharing class ContactTriggerHandler {

    public static void handle(List<Contact> newContacts, Boolean isBefore, Boolean isAfter, Boolean isInsert) {
        if (newContacts == null || newContacts.isEmpty()) {
            return;
        }
        if (isBefore) {
            onBefore(newContacts, isInsert);
        } else if (isAfter && isInsert) {
            onAfterInsert(newContacts);
        }
    }

    // ---------------------------------------------------------------------
    // BEFORE INSERT / BEFORE UPDATE
    // ---------------------------------------------------------------------
    private static void onBefore(List<Contact> contacts, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        // Single SOQL for the entire before context.
        Map<Id, Account> accountsById = new Map<Id, Account>();
        for (Account a : [SELECT Id, BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]) {
            accountsById.put(a.Id, a);
        }

        for (Contact c : contacts) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = accountsById.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    // ---------------------------------------------------------------------
    // AFTER INSERT
    // ---------------------------------------------------------------------
    private static void onAfterInsert(List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        // Single SOQL for the entire after context.
        Map<Id, Account> accountsById = new Map<Id, Account>();
        for (Account a : [SELECT Id, Phone FROM Account WHERE Id IN :accountIds]) {
            accountsById.put(a.Id, a);
        }

        // Iterate in trigger order; mutate the Account record in the map so the
        // "first qualifying contact wins" rule is honoured. Subsequent contacts
        // pointing at the same Account will see Phone already non-blank.
        Set<Id> alreadyQueued = new Set<Id>();
        List<Account> accountsToUpdate = new List<Account>();
        for (Contact c : contacts) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            Account a = accountsById.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(a.Phone)) {
                a.Phone = c.Phone;
            }
            // Queue for update only if this contact is the one that actually
            // set the phone (i.e. we transitioned it from blank to a value).
            if (!alreadyQueued.contains(a.Id) && String.isNotBlank(a.Phone) && a.Phone == c.Phone) {
                accountsToUpdate.add(a);
                alreadyQueued.add(a.Id);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate; // single DML for the whole trigger logic
        }
    }
}
