public class LogPurgeJob implements Schedulable {
    private static final String JOB_NAME = 'Log purge (nightly)';
    private static final String NIGHTLY_CRON = '0 0 2 * * ?';
    private static final Integer BATCH_CHUNK_SIZE = 10000;
    private static final Integer DIRECT_PURGE_ROW_LIMIT = 50000;

    public LogPurgeJob() {}

    public void execute(SchedulableContext sc) {
        purge();
    }

    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, NIGHTLY_CRON, new LogPurgeJob());
    }

    @TestVisible
    private void purge() {
        Datetime cutoffThirty = Datetime.now().addDays(-30);
        Datetime cutoffOneEighty = Datetime.now().addDays(-180);

        Integer eligibleRows = countEligible(cutoffThirty, cutoffOneEighty);
        if (eligibleRows == 0) {
            return;
        }

        Integer chunkSize = BATCH_CHUNK_SIZE;
        Boolean directSafe = eligibleRows <= DIRECT_PURGE_ROW_LIMIT
            && eligibleRows <= Limits.getLimitDmlRows()
            && eligibleRows <= Limits.getLimitQueryRows();

        if (!directSafe) {
            Database.executeBatch(new LogPurgeBatch(cutoffThirty, cutoffOneEighty), chunkSize);
            return;
        }

        Boolean keepDeleting = true;

        while (keepDeleting) {
            List<FB_Integration_Log__c> records = new List<FB_Integration_Log__c>();

            for (FB_Integration_Log__c logRecord : [
                SELECT Id
                FROM FB_Integration_Log__c
                WHERE (CreatedDate < :cutoffThirty AND (Level__c IS NULL OR Level__c != 'ERROR'))
                   OR (CreatedDate < :cutoffOneEighty AND Level__c = 'ERROR')
                ORDER BY CreatedDate
                LIMIT :chunkSize
            ]) {
                records.add(logRecord);
            }

            if (records.isEmpty()) {
                break;
            }

            List<Database.DeleteResult> deleteResults = Database.delete(records, false);

            Boolean deletedAny = false;
            for (Database.DeleteResult deleteResult : deleteResults) {
                if (deleteResult.isSuccess()) {
                    deletedAny = true;
                    break;
                }
            }

            if (!deletedAny || records.size() < chunkSize) {
                keepDeleting = false;
            }

            if (keepDeleting &&
                (Limits.getQueries() >= 90 ||
                 Limits.getDmlRows() >= Limits.getLimitDmlRows() - chunkSize)) {
                Database.executeBatch(new LogPurgeBatch(cutoffThirty, cutoffOneEighty), chunkSize);
                keepDeleting = false;
            }
        }
    }

    @TestVisible
    private Integer countEligible(Datetime cutoffThirty, Datetime cutoffOneEighty) {
        Integer eligibleRows = 0;

        for (AggregateResult aggregateResult : [
            SELECT COUNT()
            FROM FB_Integration_Log__c
            WHERE (CreatedDate < :cutoffThirty AND (Level__c IS NULL OR Level__c != 'ERROR'))
