public with sharing class OpportunityRollupService {
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();

        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        Set<Id> accountIdsForQuery = new Set<Id>();

        for (Id accountId : accountIds) {
            if (accountId == null) {
                continue;
            }

            result.put(accountId, Decimal.valueOf(0));

            if (accountId.getSObjectType() == Account.SObjectType) {
                accountIdsForQuery.add(accountId);
            }
        }

        if (accountIdsForQuery.isEmpty()) {
            return result;
        }

        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) wonAmount
            FROM Opportunity
            WHERE IsWon = true
                AND CloseDate = THIS_YEAR
                AND AccountId IN :accountIdsForQuery
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) ar.get('AccountId');
            Decimal wonAmount = (Decimal) ar.get('wonAmount');

            if (result.containsKey(accountId)) {
                result.put(accountId, wonAmount == null ? Decimal.valueOf(0) : wonAmount);
            }
        }

        return result;
    }
}
