@IsTest
private class OpportunityForecastServiceTest {

    private static IOpportunitiesSelector registerSelectorMock(fflib_ApexMocks mocks) {
        IOpportunitiesSelector mockSelector =
            (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);

        mocks.startStubbing();
        mocks.when(mockSelector.getSObjectType()).thenReturn(Opportunity.SObjectType);
        mocks.stopStubbing();

        Application.Selector.setMock(mockSelector);
        return mockSelector;
    }

    private static Opportunity buildOpportunity(
        Id accountId,
        String stageName,
        Decimal amount,
        Decimal probability
    ) {
        return new Opportunity(
            Id = fflib_IDGenerator.generate(Opportunity.SObjectType),
            AccountId = accountId,
            StageName = stageName,
            Amount = amount,
            Probability = probability
        );
    }

    @IsTest
    static void weightedAmountByStageWithNullAccountIdsReturnsEmptyAndDoesNotCallSelector() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector mockSelector = registerSelectorMock(mocks);

        mocks.startStubbing();
        mocks.when(
            mockSelector.selectOpenByAccountIds((Set<Id>) mocks.any())
        ).thenReturn(new List<Opportunity>());
        mocks.stopStubbing();

        Map<String, Decimal> actual =
            OpportunityForecastService.weightedAmountByStage(null);

        System.assert(actual != null, 'Expected an empty map, not null.');
        System.assert(actual.isEmpty(), 'Expected an empty map for null account ids.');

        mocks.verify(
            mockSelector.selectOpenByAccountIds((Set<Id>) mocks.any()),
            0
        );
    }

    @IsTest
