public class Opportunities extends fflib_SObjectDomain {

    public Opportunities(List<Opportunity> opportunities) {
        super(opportunities);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities((List<Opportunity>) sObjectList);
        }
    }

    public override void validate() {
        super.validate();

        if (Trigger.isInsert || Trigger.isUpdate) {
            validateAmountNegative();
        }

        if (Trigger.isUpdate) {
            validateClosedWonAmountChange();
        }
    }

    private void validateAmountNegative() {
        for (SObject obj : getRecords()) {
            Opportunity opp = (Opportunity) obj;
            if (opp.Amount != null && opp.Amount < 0) {
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }
        }
    }

    private void validateClosedWonAmountChange() {
        for (SObject obj : getRecords()) {
            Opportunity opp = (Opportunity) obj;
            Opportunity oldOpp = (Opportunity) Trigger.oldMap.get(opp.Id);

            if (oldOpp != null
                && oldOpp.StageName == 'Closed Won'
                && oldOpp.Amount != opp.Amount) {
                error('Amount cannot change on a won opportunity.', opp, Opportunity.Amount);
            }
        }
    }
}
