public with sharing class AccountRatingService {
    private static final Decimal HOT_PIPELINE_AMOUNT = 100000;

    @future
    public static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        List<Id> targetAccountIds = new List<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                targetAccountIds.add(accountId);
            }
        }

        if (targetAccountIds.isEmpty()) {
            return;
        }

        Map<Id, Decimal> maxOpenAmountByAccountId = new Map<Id, Decimal>();

        for (AggregateResult result : [
            SELECT AccountId, MAX(Amount) maxOpenAmount
            FROM Opportunity
            WHERE AccountId IN :targetAccountIds
              AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) result.get('AccountId');
            Decimal maxOpenAmount = (Decimal) result.get('maxOpenAmount');

            if (accountId != null) {
                maxOpenAmountByAccountId.put(accountId, maxOpenAmount);
            }
        }

        List<Account> accountsToUpdate = new List<Account>();

        for (Account account : [
            SELECT Id, Rating
            FROM Account
            WHERE Id IN :targetAccountIds
        ]) {
            String desiredRating;

            if (maxOpenAmountByAccountId.containsKey(account.Id)) {
                Decimal maxOpenAmount = maxOpenAmountByAccountId.get(account.Id);

                if (maxOpenAmount != null && maxOpenAmount >= HOT_PIPELINE_AMOUNT) {
                    desiredRating = 'Hot';
                } else {
                    desiredRating = 'Warm';
                }
            } else {
                desiredRating = 'Cold';
            }

            if (account.Rating != desiredRating) {
                accountsToUpdate.add(new Account(
                    Id = account.Id,
                    Rating = desiredRating
                ));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
