/**
 * Bulk-safe renewal reminder service.
 *
 * Why the original "one Messaging.sendEmail call per opportunity" idea is a bad idea:
 * - Apex has a governor limit of 10 email calls per transaction.
 * - The scheduled job passes up to 200 opportunities, so calling Messaging.sendEmail inside
 *   a per-opportunity loop will throw a LimitException before all reminders are sent.
 * - Messaging.sendEmail already supports sending many messages in one call and, when
 *   allOrNone = false, reports per-message success in Messaging.SendEmailResult. This lets
 *   individual message failures not stop the rest without consuming 200 email calls.
 *
 * This implementation builds all emails, filters to valid User owners, then sends in chunks
 * sized to stay within the 10 email-call governor limit for the stated 200-record job.
 */
public without sharing class RenewalReminderService {

    private static final Integer MAX_EMAIL_CALLS_PER_TRANSACTION = 10;
    private static final Integer MAX_EMAILS_PER_CALL = 100;
    private static final Integer SUBJECT_MAX_LENGTH = 255;

    public static Integer sendReminders(List<Id> opportunityIds) {
        Integer sentSuccessfully = 0;

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return sentSuccessfully;
        }

        // Deduplicate and keep only Opportunity record Ids.
        Set<Id> uniqueOpportunityIds = new Set<Id>();
        List<Id> orderedOpportunityIds = new List<Id>();

        for (Id recordId : opportunityIds) {
            if (recordId == null) {
                continue;
            }

            if (recordId.getSObjectType() != Opportunity.SObjectType) {
                continue;
            }

            if (!uniqueOpportunityIds.contains(recordId)) {
                uniqueOpportunityIds.add(recordId);
                orderedOpportunityIds.add(recordId);
            }
        }

        if (uniqueOpportunityIds.isEmpty()) {
            return sentSuccessfully;
        }

        // Bulk-safe query: one SOQL query for all requested opportunities.
        Map<Id, Opportunity> opportunitiesById = new Map<Id, Opportunity>(
            [
                SELECT Id, Name, OwnerId, CloseDate
                FROM Opportunity
                WHERE Id IN :uniqueOpportunityIds
            ]
        );

        List<Messaging.Email> messages = new List<Messaging.Email>();

        for (Id opportunityId : orderedOpportunityIds) {
            Opportunity opportunity = opportunitiesById.get(opportunityId);

            if (opportunity == null || opportunity.OwnerId == null) {
                continue;
            }

            // setTargetObjectId accepts Contact, Lead, or User Ids.
            // Opportunity owner may be a Queue/Group; sending directly to that would fail.
            // Keep only Users whose Id key prefix is 005.
            if (!String.valueOf(opportunity.OwnerId).startsWith('005')) {
                continue;
            }

            String opportunityName =
                opportunity.Name == null ? 'Opportunity' : opportunity.Name;

            String subject = 'Renewal due: ' + opportunityName;

            // Email subject max length is 255 characters.
            if (subject.length() > SUBJECT_MAX_LENGTH) {
                subject = subject.substring(0, SUBJECT_MAX_LENGTH);
            }

            String closeDateText =
                opportunity.CloseDate == null ? 'unknown' : opportunity.CloseDate.format();

            String plainTextBody =
                'Renewal reminder for opportunity: ' + opportunityName +
                '. Close date: ' + closeDateText + '.';

            Messaging.SingleEmailMessage message = new Messaging.SingleEmailMessage();
            message.setTargetObjectId(opportunity.OwnerId);
            message.setSaveAsActivity(false);
            message.setSubject(subject);
            message.setPlainTextBody(plainTextBody);

            messages.add(message);
        }

        if (messages.isEmpty()) {
            return sentSuccessfully;
        }

        Integer chunkSize = calculateChunkSize(messages.size());

        for (Integer startIndex = 0; startIndex < messages.size(); startIndex += chunkSize) {
            Integer endIndex = startIndex + chunkSize;

            if (endIndex > messages.size()) {
                endIndex = messages.size();
            }

            List<Messaging.Email> chunk = new List<Messaging.Email>();

            for (Integer i = startIndex; i < endIndex; i++) {
                chunk.add(messages[i]);
            }

            if (chunk.isEmpty()) {
                continue;
            }

            // allOrNone = false allows remaining messages in the call to continue
            // even if an individual message fails.
            Messaging.SendEmailResult[] results = Messaging.sendEmail(chunk, false);

            if (results != null) {
                for (Messaging.SendEmailResult result : results) {
                    if (result != null && result.isSuccess()) {
                        sentSuccessfully++;
                    }
                }
            }
        }

        return sentSuccessfully;
    }

    /**
     * Choose a chunk size that keeps the total number of Messaging.sendEmail calls
     * within the Apex governor limit for the expected workload.
     */
    private static Integer calculateChunkSize(Integer messageCount) {
        if (messageCount <= 1) {
            return 1;
        }

        Integer safeChunkSize =
            (messageCount + MAX_EMAIL_CALLS_PER_TRANSACTION - 1) /
            MAX_EMAIL_CALLS_PER_TRANSACTION;

        if (safeChunkSize < 1) {
            safeChunkSize = 1;
        }

        if (safeChunkSize > MAX_EMAILS_PER_CALL) {
            safeChunkSize = MAX_EMAILS_PER_CALL;
        }

        return safeChunkSize;
    }
}
