public with sharing class AccountCountrySync {
    private static Boolean isProcessing = false;

    public static void handleAfterUpdate(
        List<Account> updatedAccounts,
        Map<Id, Account> oldAccountsByAccountId
    ) {
        if (isProcessing) {
            return;
        }

        isProcessing = true;

        try {
            Map<Id, String> newBillingCountryByAccountId = new Map<Id, String>();
            Map<Id, String> previousBillingCountryByAccountId = new Map<Id, String>();
            Set<String> previousBillingCountries = new Set<String>();

            for (Account updatedAccount : updatedAccounts) {
                Account oldAccount = oldAccountsByAccountId.get(updatedAccount.Id);

                if (oldAccount == null) {
                    continue;
                }

                String newBillingCountry = updatedAccount.BillingCountry;
                String previousBillingCountry = oldAccount.BillingCountry;

                // Ignore exact matches and also ignore blank-to-blank changes,
                // such as null to empty string, to avoid unnecessary work.
                if (
                    newBillingCountry == previousBillingCountry ||
                    (String.isBlank(newBillingCountry) && String.isBlank(previousBillingCountry))
                ) {
                    continue;
                }

                newBillingCountryByAccountId.put(updatedAccount.Id, newBillingCountry);
                previousBillingCountryByAccountId.put(updatedAccount.Id, previousBillingCountry);

                if (String.isNotBlank(previousBillingCountry)) {
                    previousBillingCountries.add(previousBillingCountry);
                }
            }

            if (newBillingCountryByAccountId.isEmpty()) {
                return;
            }

            Set<Id> changedAccountIds = newBillingCountryByAccountId.keySet();
            List<Contact> candidateContacts;

            if (previousBillingCountries.isEmpty()) {
                candidateContacts = [
                    SELECT Id, AccountId, MailingCountry
                    FROM Contact
                    WHERE AccountId IN :changedAccountIds
                      AND (
                          MailingCountry = NULL
                          OR MailingCountry = ''
                      )
                    WITH USER_MODE
                ];
            } else {
                candidateContacts = [
                    SELECT Id, AccountId, MailingCountry
                    FROM Contact
                    WHERE AccountId IN :changedAccountIds
                      AND (
                          MailingCountry = NULL
                          OR MailingCountry = ''
                          OR MailingCountry IN :previousBillingCountries
                      )
                    WITH USER_MODE
                ];
            }

            List<Contact> contactsToUpdate = new List<Contact>();

            for (Contact candidateContact : candidateContacts) {
                String previousBillingCountry = previousBillingCountryByAccountId.get(
                    candidateContact.AccountId
                );

                String newBillingCountry = newBillingCountryByAccountId.get(
                    candidateContact.AccountId
                );

                if (
                    String.isBlank(candidateContact.MailingCountry) ||
                    candidateContact.MailingCountry == previousBillingCountry
                ) {
                    if (candidateContact.MailingCountry != newBillingCountry) {
                        candidateContact.MailingCountry = newBillingCountry;
                        contactsToUpdate.add(candidateContact);
                    }
                }
            }

            if (!contactsToUpdate.isEmpty()) {
                update contactsToUpdate;
            }
        } finally {
            isProcessing = false;
        }
    }
}
