import { LightningElement, api, track } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label = '';

    @track _options = [];
    @track _rawOptions = [];
    @track _value = undefined;
    @track _activeIndex = -1;
    @track _selectedIndex = -1;

    _prefix;

    constructor() {
        super();
        this._prefix = `status-listbox-${Math.random().toString(36).slice(2, 10)}`;
    }

    @api
    get options() {
        return this._rawOptions;
    }

    set options(options) {
        this._rawOptions = options;
        this._normalizeOptions();
    }

    @api
    get value() {
        return this._value;
    }

    set value(value) {
        this._value = value;
        this._syncSelection();
    }

    get renderedOptions() {
        return this._options;
    }

    get activeId() {
        const option = this._options[this._activeIndex];
        return option ? option.id : undefined;
    }

    handleKeyDown(event) {
        switch (event.key) {
            case 'ArrowDown':
                event.preventDefault();
                this._moveActive(1);
                break;
            case 'ArrowUp':
                event.preventDefault();
                this._moveActive(-1);
                break;
            case 'Home':
                event.preventDefault();
                this._setActive(0);
                break;
            case 'End':
                event.preventDefault();
                this._setActive(this._options.length - 1);
                break;
            case 'Enter':
                event.preventDefault();
                this._select(this._activeIndex, false);
                break;
            case ' ':
                event.preventDefault();
                this._select(this._activeIndex, false);
                break;
            default:
                break;
        }
    }

    handleOptionClick(event) {
        const element = event.currentTarget || event.target;
        let index = -1;

        if (element) {
            const id = element.id;
            if (id) {
                index = this._options.findIndex((option) => option.id === id);
            }

            if (index < 0) {
                const dataValue = element.dataset ? element.dataset.value : undefined;
                index = this._options.findIndex((option) => this._isSame(option.value, dataValue));
            }
        }

        if (index >= 0) {
            this._select(index, true);
        }
    }

    _normalizeOptions() {
        const source = Array.isArray(this._rawOptions) ? this._rawOptions : [];

        this._options = source.map((item, index) => ({
            value: item ? item.value : undefined,
            label: item ? item.label : '',
            id: `${this._prefix}-${index}`,
            selected: 'false'
        }));

        this._syncSelection();
    }

    _syncSelection() {
        const selectedIndex = this._options.findIndex((option) => this._isSame(option.value, this._value));

        this._selectedIndex = selectedIndex;

        this._options = this._options.map((option, index) => ({
            ...option,
            selected: index === selectedIndex ? 'true' : 'false'
        }));

        if (selectedIndex >= 0) {
            this._activeIndex = selectedIndex;
        } else if (this._options.length > 0) {
            this._activeIndex = 0;
        } else {
            this._activeIndex = -1;
        }
    }

    _select(index, makeActive) {
        if (index < 0 || index >= this._options.length) {
            return;
        }

        if (makeActive) {
            this._activeIndex = index;
        }

        const option = this._options[index];

        if (this._isSame(this._value, option.value)) {
            return;
        }

        this._value = option.value;
        this._syncSelection();

        this.dispatchEvent(
            new CustomEvent('change', {
                detail: {
                    value: this._value
                },
                bubbles: true
            })
        );
    }

    _moveActive(delta) {
        if (this._options.length === 0) {
            return;
        }

        let next = this._activeIndex + delta;

        if (next < 0) {
            next = 0;
        } else if (next >= this._options.length) {
            next = this._options.length - 1;
        }

        this._activeIndex = next;
    }

    _setActive(index) {
        if (this._options.length === 0) {
            return;
        }

        if (index < 0) {
            index = 0;
        } else if (index >= this._options.length) {
            index = this._options.length - 1;
        }

        this._activeIndex = index;
    }

    _isSame(a, b) {
        if (a === b) {
            return true;
        }

        if (a == null || b == null) {
            return false;
        }

        return String(a) === String(b);
    }
}
