    }

    handleAdd() {
        const label = this.newLabel ? String(this.newLabel).trim() : '';
        if (!label) {
            return;
        }

        const newTask = {
            id: `new-${this._nextId++}`,
            label,
            done: false,
        };

        this._items = [...this._items, newTask];
        this.newLabel = '';

        this.dispatchEvent(
            new CustomEvent('taskadded', {
                detail: { label },
                bubbles: true,
                composed: true,
            })
        );
    }

    handleToggle(event) {
        const source = event.currentTarget || event.target;
        const id = source && source.dataset ? source.dataset.id : undefined;

        if (id === undefined || id === null) {
            return;
        }

        const index = this._items.findIndex(
            (task) => String(task.id) === String(id)
        );

        if (index === -1) {
            return;
        }

        const updated = [...this._items];
        updated[index] = {
            ...updated[index],
            done: !updated[index].done,
        };

        this._items = updated;
    }

    _updateNextId(items) {
        let max = this._nextId;

        items.forEach((item) => {
            const id =
                item.id === undefined || item.id === null
                    ? ''
                    : String(item.id);
            const match = /^new-(\d+)$/.exec(id);

            if (match) {
                max = Math.max(max, Number(match[1]) + 1);
            }
        });

        this._nextId = max;
    }
}
