```java
public class PaymentPlanService {

    public class PaymentPlanException extends Exception {}

    public static List<npe01__OppPayment__c> scheduleInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate
    ) {
        // --- Validate numberOfPayments before any data changes ---
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException(
                'numberOfPayments must be a non-null integer greater than or equal to 1.'
            );
        }

        // --- Fetch the opportunity ---
        Opportunity opp = [
            SELECT Id, Amount, IsClosed
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
        ];

        if (opp == null) {
            throw new PaymentPlanException('Opportunity not found.');
        }

        // --- Validate the opportunity is open ---
        if (opp.IsClosed) {
            throw new PaymentPlanException(
                'Cannot schedule a payment plan on a closed opportunity.'
            );
        }

        // --- Fetch existing payments and classify them ---
        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id, npe01__Paid__c, npe01__Written_Off__c, npe01__Payment_Amount__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
        ];

        Decimal historyTotal = 0;
        List<npe01__OppPayment__c> toDelete = new List<npe01__OppPayment__c>();

        for (npe01__OppPayment__c pmt : existingPayments) {
            Boolean isPaid = pmt.npe01__Paid__c == true;
            Boolean isWrittenOff = pmt.npe01__Written_Off__c == true;

            if (isPaid || isWrittenOff) {
                historyTotal += (pmt.npe01__Payment_Amount__c != null)
                    ? pmt.npe01__Payment_Amount__c
                    : 0;
            } else {
                toDelete.add(pmt);
            }
        }

        // --- Calculate outstanding amount ---
        Decimal oppAmount = (opp.Amount != null) ? opp.Amount : 0;
        Decimal outstanding = oppAmount - historyTotal;

        // --- Validate outstanding > 0 before any DML ---
        if (outstanding <= 0) {
            throw new PaymentPlanException(
                'Outstanding amount must be greater than zero to schedule a payment plan.'
            );
        }

        // --- Delete non-history payments ---
        if (!toDelete.isEmpty()) {
            delete toDelete;
        }

        // --- Calculate payment amounts with rounding-down and remainder absorption ---
        Decimal baseAmount = outstanding.divide(numberOfPayments, 2, RoundingMode.DOWN);
        Decimal lastAmount = outstanding - (baseAmount * (numberOfPayments - 1));

        // --- Build the new unpaid payments ---
        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();

        for (Integer i = 0; i < numberOfPayments; i++) {
            Decimal amount = (i == numberOfPayments - 1) ? lastAmount : baseAmount;

            npe01__OppPayment__c newPmt = new npe01__OppPayment__c();
            newPmt.npe01__Opportunity__c = opportunityId;
            newPmt.npe01__Payment_Amount__c = amount;
            newPmt.npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i);
            newPmt.npe01__Paid__c = false;
            newPmt.npe01__Written_Off__c = false;
            newPayments.add(newPmt);
        }

        // --- Insert new payments ---
        insert newPayments;

        // Return payments already in schedule order (built in order)
        return newPayments;
    }
}
