```apex
/**
 * Moves a book of business (Accounts + their Contacts) to a new owner.
 *
 * Account trigger actions (TAF) are bypassed for the whole reassignment because the
 * registered Account actions recalculate territories and are expensive; Contact trigger
 * actions run normally. The bypass is always released in a finally block so Account
 * automation behaves normally for the remainder of the transaction, whether we succeed
 * or an exception propagates to the caller.
 *
 * Budget: one SOQL (Contact) and at most two DML statements regardless of volume.
 */
public with sharing class AccountOwnershipService {
    // sObject-level bypass token names match the Trigger_Setting__mdt / trigger API names.
    private static final String ACCOUNT_API_NAME = 'Account';

    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Read Contacts *before* changing Account ownership: sharing rule recalculation is
        // asynchronous, so an ownership flip can move rows out of the running user's view.
        // Only Id is needed; assigning OwnerId makes it the only field sent in the update.
        List<Contact> contacts = [SELECT Id FROM Contact WHERE AccountId IN :accountIds];

        List<Account> accounts = new List<Account>();
        for (Id accountId : accountIds) {
            accounts.add(new Account(Id = accountId, OwnerId = newOwnerId));
        }
        for (Contact contact : contacts) {
            contact.OwnerId = newOwnerId;
        }

        try {
            // Whole-sObject transaction bypass (not per-action) for Account only.
            TriggerBase.bypass(ACCOUNT_API_NAME);

            // allOrNone = true; any DmlException propagates unchanged after the finally runs.
            Database.update(accounts, true);

            if (!contacts.isEmpty()) {
                // Contact automation is not bypassed, so all Contact actions fire normally.
                Database.update(contacts, true);
            }
        } finally {
            // Guarantee Account automation is restored for the rest of the transaction,
            // on success and on failure.
            TriggerBase.clearBypass(ACCOUNT_API_NAME);
        }
    }
}
