```apex
/**
 * Trigger action that collects Opportunity Ids that need to be pushed to the ERP.
 *
 * The collected Ids are stored in transaction-scoped static memory so that all
 * chunks of a single bulk DML operation can be aggregated into one async job.
 * The DML finalizer is responsible for enqueueing the job and clearing the
 * pending set.
 */
public with sharing class TA_Opportunity_CollectForErpSync
        implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {

    private static final Set<Id> pendingOpportunityIds = new Set<Id>();

    public void afterInsert(List<SObject> triggerNew) {
        for (SObject record : triggerNew) {
            pendingOpportunityIds.add(record.Id);
        }
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Opportunity> oldOppsById = new Map<Id, Opportunity>();

        for (SObject oldRecord : triggerOld) {
            oldOppsById.put(oldRecord.Id, (Opportunity) oldRecord);
        }

        for (SObject newRecord : triggerNew) {
            Opportunity newOpp = (Opportunity) newRecord;
            Opportunity oldOpp = oldOppsById.get(newOpp.Id);

            if (oldOpp != null && newOpp.StageName != oldOpp.StageName) {
                pendingOpportunityIds.add(newOpp.Id);
            }
        }
    }

    public static Boolean hasPendingOpportunityIds() {
        return !pendingOpportunityIds.isEmpty();
    }

    public static Set<Id> takePendingOpportunityIds() {
        Set<Id> idsToSync = pendingOpportunityIds.clone();
        pendingOpportunityIds.clear();
        return idsToSync;
    }

    public static void clearPendingOpportunityIds() {
        pendingOpportunityIds.clear();
    }
}
