File: force-app/main/default/classes/OpportunityErpSyncFinalizer.cls
```apex
/**
 * TAF DML finalizer that enqueues exactly one ERP sync job per Opportunity
 * DML operation.
 *
 * TAF calls every registered DML finalizer at the end of every DML operation
 * it handles, regardless of sObject. This finalizer therefore only consumes the
 * pending Opportunity Ids when the finalizer invocation corresponds to an
 * Opportunity insert/update context. If Trigger context is unavailable (for
 * example in direct unit-test invocation), it processes whatever Opportunity
 * ids have already been collected.
 */
public with sharing class OpportunityErpSyncFinalizer implements TriggerAction.DmlFinalizer {

    public void execute(FinalizerHandler.Context context) {
        if (!TA_Opportunity_CollectForErpSync.hasPendingOpportunityIds()) {
            return;
        }

        if (!isOpportunitySyncDmlContext()) {
            return;
        }

        Set<Id> opportunityIdsToSync = TA_Opportunity_CollectForErpSync.takePendingOpportunityIds();

        if (!opportunityIdsToSync.isEmpty()) {
            System.enqueueJob(new OpportunityErpSyncJob(opportunityIdsToSync));
        }
    }

    private static Boolean isOpportunitySyncDmlContext() {
        if (!Trigger.isExecuting) {
            return true;
        }

        return Trigger.newSobjectType == Schema.Opportunity.SObjectType &&
               (Trigger.isInsert || Trigger.isUpdate);
    }
}
