@isTest
public class TA_Opportunity_GuardAmountDecreaseTest {
    private static Id fakeOpportunityId() {
        return TriggerTestUtility.getFakeId(Opportunity.SObjectType);
    }

    private static Opportunity buildOpportunity(Id recordId, Decimal amount) {
        return new Opportunity(Id = recordId, Amount = amount);
    }

    private static void invokeBeforeUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();
        action.beforeUpdate(triggerNew, triggerOld);
    }

    private static void assertRejected(Opportunity record, String expectedErrorMessage, String context) {
        System.assert(record.hasErrors(), context + ': expected the guard error.');

        List<Database.Error> errors = record.getErrors();
        System.assert(errors != null, context + ': expected a non-null error list.');

        System.assertEquals(1, errors.size(), context + ': expected exactly one error.');
        System.assertEquals(expectedErrorMessage, errors[0].getMessage(), context + ': unexpected error message.');
    }

    private static void assertAccepted(Opportunity record, String context) {
        System.assert(!record.hasErrors(), context + ': expected no errors.');

        List<Database.Error> errors = record.getErrors();
        if (errors != null) {
            System.assertEquals(0, errors.size(), context + ': expected no errors.');
        }
    }

    @isTest
    private static void decreaseByMoreThanHalfIsRejected() {
        Id oppId = fakeOpportunityId();
        Opportunity newRecord = buildOpportunity(oppId, 499);
        Opportunity oldRecord = buildOpportunity(oppId, 1000);

        invokeBeforeUpdate(
            new List<Opportunity>{ newRecord },
            new List<Opportunity>{ oldRecord }
        );

        assertRejected(
            newRecord,
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            'Decrease from 1000 to 499'
        );
    }

    @isTest
    private static void exactHalfIncreaseAndNullPreviousAmountAreAccepted() {
        Id exactHalfId = fakeOpportunityId();
        Opportunity exactHalfNew = buildOpportunity(exactHalfId, 500);
        Opportunity exactHalfOld = buildOpportunity(exactHalfId, 1000);

        Id increaseId = fakeOpportunityId();
        Opportunity increaseNew = buildOpportunity(increaseId, 1500);
        Opportunity increaseOld = buildOpportunity(increaseId, 1000);

        Id nullPreviousId = fakeOpportunityId();
        Opportunity nullPreviousNew = buildOpportunity(nullPreviousId, 499);
        Opportunity nullPreviousOld = buildOpportunity(nullPreviousId, null);

        invokeBeforeUpdate(
            new List<Opportunity>{ exactHalfNew, increaseNew, nullPreviousNew },
            new List<Opportunity>{ exactHalfOld, increaseOld, nullPreviousOld }
        );

        assertAccepted(exactHalfNew, 'Decrease to exactly half');
        assertAccepted(increaseNew, 'Increase');
        assertAccepted(nullPreviousNew, 'Previous amount null');
    }

    @isTest
    private static void batchOnlyViolatingRecordsAreRejected() {
        Id violationOneId = fakeOpportunityId();
        Opportunity violationOneNew = buildOpportunity(violationOneId, 499);
        Opportunity violationOneOld = buildOpportunity(violationOneId, 1000);

        Id compliantOneId = fakeOpportunityId();
        Opportunity compliantOneNew = buildOpportunity(compliantOneId, 500);
        Opportunity compliantOneOld = buildOpportunity(compliantOneId, 1000);

        Id violationTwoId = fakeOpportunityId();
        Opportunity violationTwoNew = buildOpportunity(violationTwoId, 0);
        Opportunity violationTwoOld = buildOpportunity(violationTwoId, 1000);

        Id compliantTwoId = fakeOpportunityId();
        Opportunity compliantTwoNew = buildOpportunity(compliantTwoId, null);
        Opportunity compliantTwoOld = buildOpportunity(compliantTwoId, 1000);

        invokeBeforeUpdate(
            new List<Opportunity>{ violationOneNew, compliantOneNew, violationTwoNew, compliantTwoNew },
            new List<Opportunity>{ violationOneOld, compliantOneOld, violationTwoOld, compliantTwoOld }
        );

        assertRejected(
            violationOneNew,
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            'First violating record'
        );
        assertRejected(
            violationTwoNew,
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            'Second violating record'
        );
        assertAccepted(compliantOneNew, 'First compliant record');
        assertAccepted(compliantTwoNew, 'Second compliant record');
    }
}
