public without sharing class TA_Case_RollupOpenCount implements
    TriggerAction.AfterInsert,
    TriggerAction.AfterUpdate,
    TriggerAction.AfterDelete,
    TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        process(triggerNew, null);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        process(triggerNew, triggerOld);
    }

    public void afterDelete(List<SObject> triggerOld) {
        process(triggerOld, null);
    }

    public void afterUndelete(List<SObject> triggerNew) {
        process(triggerNew, null);
    }

    private void process(List<SObject> newRecords, List<SObject> oldRecords) {
        Set<Id> accountIds = collectAccountIds(newRecords);
        accountIds.addAll(collectAccountIds(oldRecords));

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Integer> openCaseCounts = new Map<Id, Integer>();

        for (AggregateResult result : [
            SELECT COUNT(Id) cnt, AccountId
            FROM Case
            WHERE IsClosed = false
            AND AccountId IN :accountIds
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) result.get('AccountId');
            Integer cnt = (Integer) result.get('cnt');

            if (accountId != null && cnt != null) {
                openCaseCounts.put(accountId, cnt);
            }
        }

        List<Account> accountsToUpdate = new List<Account>();

        for (Id accountId : accountIds) {
            accountsToUpdate.add(new Account(
                Id = accountId,
                FB_Open_Case_Count__c = openCaseCounts.containsKey(accountId)
                    ? openCaseCounts.get(accountId)
                    : 0
            ));
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }

    private Set<Id> collectAccountIds(List<SObject> records) {
        Set<Id> accountIds = new Set<Id>();

        if (records == null) {
            return accountIds;
        }

        for (SObject record : records) {
            Id accountId = (Id) record.get('AccountId');

            if (accountId != null) {
                accountIds.add(accountId);
            }
        }

        return accountIds;
    }
}
